#ifndef CONV2D_FILTER_REGS_H
#define CONV2D_FILTER_REGS_H
#define CONV2D_FILTER_REGS_ID_OFFSET 0x00u
#define CONV2D_FILTER_REGS_VERSION_OFFSET 0x04u
#define CONV2D_FILTER_REGS_DATE_OFFSET 0x08u
#define CONV2D_FILTER_REGS_ID_VALUE 0x43324446u   /* "C2DF" */
#define CONV2D_FILTER_REGS_FRAME_SIZE_OFFSET 0x14u   /* RW */
#define CONV2D_FILTER_REGS_SHIFT_OFFSET 0x18u   /* RW */
#define CONV2D_FILTER_REGS_STATUS_OFFSET 0x1Cu   /* RO */
#define CONV2D_FILTER_REGS_STATUS_RESET 0x00000000u
#define CONV2D_FILTER_REGS_INFO_OFFSET 0x20u   /* RO */
#define CONV2D_FILTER_REGS_INFO_RESET 0x00000000u
#define CONV2D_FILTER_REGS_K_OFFSET 0x50u   /* RW array, stride 4 */
#define CONV2D_FILTER_REGS_K_STRIDE 4u
#endif /* CONV2D_FILTER_REGS_H */
